import numpy as np
def allcols(b):
    E=np.exp(-b*t)
    G={'1':np.ones_like(t),'E':E,'t':t,'tE':t*E}
    cols={}
    for gn,g in G.items():
        for j in range(4):
            cols[f"{gn}*P^{j}"]=g*P**j
    return cols
def greedy(b,K=9):
    cols=allcols(b); sel=[]
    for _ in range(K):
        bestn=None
        for n in cols:
            if n in sel: continue
            A=np.array([cols[s] for s in sel+[n]]).T
            c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
            e=np.mean((A@c-dP_dt)**2)/np.var(dP_dt)
            if bestn is None or e<bestn[0]: bestn=(e,n)
        sel.append(bestn[1])
    A=np.array([cols[s] for s in sel]).T
    c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
    return sel,c,bestn[0]
for b in [0.5,0.54,0.6]:
    sel,c,e=greedy(b,9)
    print(b,'%.3e'%e,list(zip(sel,np.round(c,4))))

